arguments.command:
python3 - <<'EOF'
p='src/run.test.ts'
s=open(p).read()
anchor='	it("logs the thread first, then what pi does, the reply, and where the thread ends up", async () => {'
new='''	it("applies model_tools_hidden on each run, and clears it when the input is empty", async () => {
		const w = world();
		const seen: string[][] = [];
		const record: FauxResponseStep = (context) => {
			seen.push(toolsOf(context).map((tool) => tool.name));
			return fauxAssistantMessage("ok");
		};
		w.faux.setResponses([record, record]);

		const hidden = w.deps(w.comment("@pi one"), { modelToolsHidden: ["bash"] });
		await run(hidden);
		await run(w.deps(w.comment("@pi two")));

		expect(seen).toStrictEqual([
			["read", "write", "edit"],
			["read", "write", "edit", "bash"],
		]);
		expect(hidden.log.info).toHaveBeenCalledWith(
			expect.stringMatching(/ · tools: read, write, edit$/u),
		);
	});

'''
s=s.replace(anchor,new+anchor,1)
s=s.replace("""	tempDir,
	tempRemote,
} from "./test-helpers.ts";""","""	tempDir,
	tempRemote,
	toolsOf,
} from "./test-helpers.ts";""")
open(p,'w').write(s)
EOF
npx vitest run src/run.test.ts -t "model_tools_hidden|logs the thread" 2>&1 | grep -v "^::" | tail -20
